export function getBlogPostBySlug(slug: string): BlogPostItem | undefined {
  return BLOG_POSTS.find((b) => b.slug === slug);
}

export function getBlogCategoryBySlug(category: string): BlogCategoryItem | undefined {
  return BLOG_CATEGORIES.find((c) => c.category === category);
}
